import React, { useRef, useState } from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    ActivityIndicator,
    Animated
} from 'react-native';

import { ParamListBase, useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';

import { Alert } from '../../components/Pop-Ups/Alert';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';
import { styles } from './styles';

import api from '../../services/api';

type YourNavigatorProps = NativeStackNavigationProp<ParamListBase, keyof ParamListBase>

interface CardsProps {
    position: number;
    listItemProps: {
        data: { firstCard: number, id: string };
        list?: {
            [key: string]: [{
                id: number;
                name: string;
                phone: string;
                price: number;

                analyzed: number;
            }]
        };
    };
};


interface response {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
    }[]
};


export function Cards({ listItemProps, position }: CardsProps) {
    const [checkBuyLoad, setCheckBuyLoad] = useState(false)
    const cardNumber = listItemProps.data.firstCard + position;
    const randomText = Math.random().toString(36).substr(2, 5);
    const fadeAnim = useRef(new Animated.Value(0.9)).current;

    const {
        isMountedApi,
        shoppingCartItem,
        alertMessage,
        listData,
    } = useContexState();

    const {
        setKeyboardActive,
        setSelectedNumber,
        setAlertActive,
        setPaymentMenuActive,
        setAlertMessage
    } = useContexState();

    const tempShoppingCartItem = [...shoppingCartItem];
    const index = tempShoppingCartItem.indexOf(cardNumber);
    const navigation = useNavigation<YourNavigatorProps>();

    const { LoadPage } = useLoadPage();
    const { AlertButton } = Alert(props = {listItemProps, position});

    function colorSelect() {
        if (shoppingCartItem[index]) {
            return { backgroundColor: '#7B68EE' };
        };

        if (listItemProps.list?.[String(cardNumber)]) {
            return {
                backgroundColor: listItemProps.list?.
                [cardNumber][0].analyzed !== 0 ? '#26A744' : '#17A2B7'
            };
        } else {
            return {
                backgroundColor: '#fff',
                color: '#121212'
            };
        };
    };


    // onPress={() => isMountedApi ? checkBuy() : null}





    function ButtonCard() {
        return cardNumber <= 9999 && cardNumber >= 0 ? (
            <AlertButton
                value={{ listItemProps, position }}
                style={{ alignItems: 'center', justifyContent: 'center' }}>


                <Text
                    style={[styles.listText, colorSelect()]}>
                    {(`0000${cardNumber}`).slice(-4)}
                </Text>


                {!isMountedApi || checkBuyLoad ?
                    <ActivityIndicator
                        style={{ position: 'absolute' }}
                        size={20}
                        color='#121212'
                    /> : null}


            </AlertButton>
        ) : <View />
    }

    return <ButtonCard />;
};


